class AsirHubOperations(GenericAsirHub):
    """ASIR hub keywords for gNB|eNB"""

    def __init__(self, bts_type="GNB", parallel_warning=False, bts_id=0, ru=None):
        """
        Constructor of AsirHubOperations class.

        :param bts_type: GNB|ENB
        """
        super(AsirHubOperations, self).__init__(bts_type=bts_type)
        if parallel_warning is True:
            self._check_if_parallel_sessions_are_active(bts_id=bts_id)

        self.ru = ru()

    def get_hub_device(self, bts_id=0, du_id=0, ru_id=0, device_name=None, serial_number=None):
        return self.ru.get_ru_device(bts_id, du_id, ru_id, device_name, serial_number)

    def wait_for_asir_to_be_onair(self, timeout=600, bts_id=0):
        """
        Wait for ASIR enter onAir state.

        :param float timeout: time in seconds to wait for ASIR onAir state
        :param int bts_id: BTS id - related to Test Line configuration
        :return:  None
        """
        start_time = time.time()
        while time.time() - start_time < timeout:
            try:
                if self.get_site_info(bts_id=bts_id)["operational_state"] == "onAir":
                    logging.info("ASIR onAir")
                    break
                else:
                    logging.info("Waiting for ASIR to be in onAir state ...")
                    time.sleep(30)
            except AuthenticationFailed:
                logging.info("Cannot connect to ASIR Webem, waiting for reconnection ...")
                time.sleep(30)
                continue
        else:
            raise AsirNotOnAir("Timeout passed. Asir not onAir")

    @login_logout
    def perform_asir_commissioning(self, scf_path, migrate_nidd=True, bts_id=0, timeout=180):
        """
        Perform full commissioning of ASIR hub (delete actual staged plan if exists).

        :param str scf_path: path to scf configuration file
        :param int bts_id: BTS id - related to Test Line configuration
        :param migrate_nidd: flag which indicate if NIDD migration should be performed during commissioning process
        :param timeout: timeout for active plan operation
        :return: None
        """
        staged_plans_info = self._get_staged_plans(bts_id=bts_id)
        staged_delta_plans = self._get_staged_delta_plans(bts_id=bts_id)
        if staged_plans_info:
            self._delete_staged_plan(plan_id=staged_plans_info[0]["id"], bts_id=bts_id)
        if staged_delta_plans:
            self._delete_delta_plan(delta_plan_id=staged_delta_plans[0]["eid"], bts_id=bts_id)
        if migrate_nidd:
            delta_plan_id = self._create_new_delta_plan(source_plan="none", bts_id=bts_id)["eid"]
            nidd_info = self._upload_plan_template(delta_plan_id=delta_plan_id, scf_path=scf_path, bts_id=bts_id)
            if nidd_info["migration_needed"]:
                actual_nidd = nidd_info["version"]["adaptation_versions"][0]["version"]
                supported_nidd = nidd_info["supported_versions"][0]["adaptation_versions"][0]['version']
                scf_path = self._convert_scf_file_to_supported_nidd(scf_path=scf_path, actual_nidd=actual_nidd,
                                                                    supported_nidd=supported_nidd)
        plan_id = self._upload_plan(scf_path=scf_path, bts_id=bts_id)["id"]
        try:
            self._activate_plan(plan_id=plan_id, timeout=timeout, bts_id=bts_id)
        except AsirOperationFailed as e:
            logging.debug("Unable to activate plan: {}".format(e))
            logging.debug("Getting details")
            validation_results = self._perform_asir_operation(self.asir.get_validation_results)
            validation_errors = self._perform_asir_operation(self.asir.get_validation_errors)
            raise AsirOperationFailed(
                f"Unable to activate plan due to {validation_results['message']}. "
                f"Details: {validation_errors}")

    @login_gui_if_needed
    def perform_asir_commissioning_via_gui(self, scf_path, bts_id=0, timeout=180):
        """
        Perform full commissioning of ASIR hub via GUI.

        :param str scf_path: path to scf configuration file
        :param int bts_id: BTS id - related to Test Line configuration
        :param timeout: timeout for active plan operation
        :return: None
        """
        self.gui_asir.load_and_activate_configuration(scf_file_path=scf_path, sc=self.gui_alias.format(bts_id))

    @login_logout
    def perform_asir_recommissioning(self, delta, save_delta_plan=False, delta_content_type="auto",
                                     delta_file_name=None, download_dir="/tmp", bts_id=0):
        """
        Perform parameter recommissioning, "create", "update", "delete" operation can be used.
        :param list delta: list of objects/parameters to create/update/delete. Sample deltas:
            Example for changing parameters:
                delta = [{
                    'distName': dist_name,
                    'parameters': [{
                        'operation': operation,
                        'parameterName': parameter,
                        'value': value}]}]
                where:
                    dist_name: Object dist name ie. "ASI-1/HUBMOD-1"
                    parameter: Parameter name ie. "actLbEnergySaving"
                    operation: Parameter operation (create, update or delete)
                    value: Parameter value ie. "true"; set only for create and update operations
                    field: optional - structure name of target parameter
                    index: optional - index of target parameter in the array
            Example for creating objects:
                delta = [{'distName': dist_name, 'moc': object_name, 'operation': operation, 'instanceId': instance_id}]
                where:
                    dist_name: Object dist name ie. "ASI-1"
                    object_name: Managed Object Class ie. "HUBMOD"
                    operation: Object operation (create)
                    instance_id: optional - id of target object, if not specified, next available one will be assigned
            Example for deleting objects:
                delta = [{'distName': dist_name, 'operation': operation}]
                where:
                    dist_name: Object dist name ie. "ASI-1/HUBMOD-1"
                    operation: Object operation (delete)
        :param save_delta_plan: save delta plan to download_dir if save_delta_plan is True
        :param delta_content_type: type of delta file content:
            "auto" for short delta plan or "full" for full SCF containing delta plan.
        :param delta_file_name: name of delta file
        :param download_dir: path to save delta file
        :param bts_id: ID of gNB/eNB
        :raises taf.rfrl.bts.devices.exceptions.AsirOperationFailed: Will be raised if recommissioning fails
        :return: path to delta file if save_delta_plan is True
        """
        staged_delta_plans = self._get_staged_delta_plans(bts_id=bts_id)
        if staged_delta_plans:
            logging.info('Update an existing delta plan')
            delta_plan_id = staged_delta_plans[0]['eid']
        else:
            logging.info('Create a new delta plan')
            delta_plan_id = self._create_new_delta_plan(source_plan='active', bts_id=bts_id)['eid']
        for distname_params in delta:
            if 'parameters' not in distname_params:
                try:
                    distname_params["dn"] = distname_params.pop("distName") if "distName" in distname_params else \
                        distname_params["dn"]
                    self._update_object_of_delta_plan(delta_plan_id=delta_plan_id, body=[distname_params])
                except AsirOperationFailed as e:
                    logging.error('Unable to {} parameter {} under {}: {}'.format(distname_params["operation"],
                                                                                  distname_params["moc"],
                                                                                  distname_params["dn"], e))
                    raise e
            else:
                dist_name = distname_params['distName']
                parameters = distname_params['parameters']
                for parameter in parameters:
                    operation = parameter['operation']
                    value = None if operation == 'delete' else parameter['value']
                    field = parameter.get('field', None)
                    index = parameter.get('index', None)
                    logging.info('Performing {} operation for parameter: {}'.format(operation, parameter))
                    try:
                        self._update_parameter_of_delta_plan(delta_plan_id=delta_plan_id,
                                                             operation=operation,
                                                             dn=dist_name,
                                                             name=parameter['parameterName'],
                                                             value=value,
                                                             field=field,
                                                             index=index,
                                                             bts_id=bts_id)
                    except AsirOperationFailed as e:
                        logging.error('Unable to {} parameter {}: {}'.format(operation, parameter, e))
                        raise e

        delta_path = self._get_delta_plan_file(delta_plan_id=delta_plan_id, content_type=delta_content_type,
                                               local_dir_path=download_dir,
                                               file_name=delta_file_name) if save_delta_plan else None
        self._activate_delta_plan(delta_plan_id=delta_plan_id, bts_id=bts_id)
        self._delete_delta_plan(delta_plan_id=delta_plan_id, bts_id=bts_id)
        return delta_path

    def _upload_plan(self, scf_path, bts_id=0):
        """
        Upload ASIR Webem plan file.

        :param str scf_path: path to '.xml' configuration file
        :return dict: ASIR Webem staged plan dictionary
        """
        return self._perform_asir_operation(self.asir.upload_plan, scf_path)

    def _upload_plan_template(self, delta_plan_id, scf_path, bts_id=0):
        """
        Upload ASIR Webem plan template file.

        :param str delta_plan_id: id of target delta plan to load plan template
        :param str scf_path: path to '.xml' plan template file
        :return dict: ASIR Webem plan template info dictionary
        """
        return self._perform_asir_operation(self.asir.upload_plan_template, delta_plan_id, scf_path)

    def _get_staged_plans(self, bts_id=0):
        """
        Get ASIR Webem staged plans info.

        :param int bts_id: BTS id - related to Test Line configuration
        :return list: ASIR Webem staged plans info. Example return value:
        [{'id': '1', 'name': 'SCFC_1.xml'}]
        """
        return self._perform_asir_operation(self.asir.get_staged_plans)

    def _validate_plan(self, plan_id, timeout=60, bts_id=0):
        """
        Validate ASIR Webem staged plan defined by plan id.

        :param str plan_id: id of staged plan to validate
        :param float timeout: time in seconds to finish the plan operation
        :param int bts_id: BTS id - related to Test Line configuration
        :return dict: information about result of plan validation operation. Example return value:
        {"restartNeeded": true, "message": "All parameters have passed validation."}
        :raises AsirOperationTimeout: exception raised when operation on ASIR exceeds the time limit
        """
        return self._perform_asir_operation(self.asir.validate_plan, plan_id, timeout)

    def _activate_plan(self, plan_id, timeout=60, bts_id=0):
        """
        Activate ASIR Webem staged plan defined by plan id.

        :param str plan_id: id of staged plan to activate
        :param float timeout: time in seconds to finish the plan operation
        :param int bts_id: BTS id - related to Test Line configuration
        :return dict: information about result of plan activation operation. Example return value:
        {"restartNeeded": true, "message": "All parameters have passed validation."}
        :raises AsirOperationTimeout: exception raised when operation on ASIR exceeds the time limit
        """
        return self._perform_asir_operation(self.asir.activate_plan, plan_id, timeout)

    def _delete_staged_plan(self, plan_id, bts_id=0):
        """
        Delete ASIR Webem staged plan defined by plan id.

        :param str plan_id: id of staged plan to delete
        :param int bts_id: BTS id - related to Test Line configuration
        :return: None
        """
        return self._perform_asir_operation(self.asir.delete_staged_plan, plan_id)

    def _create_new_delta_plan(self, source_plan, source_plan_id=None, timeout=60, bts_id=0):
        """
        Create ASIR Webem delta plan from defined source.

        :param str source_plan: source of delta plan, possible values: ["none", "active", "staged"]
        :param str source_plan_id: id of source staged plan for new delta plan. Required if source_plan="staged"
        :param float timeout: time in seconds to finish the plan operation
        :param int bts_id: BTS id - related to Test Line configuration
        :return dict: ASIR Webem delta plan information. Example return value:
        {"eid": "4"}
        """
        return self._perform_asir_operation(self.asir.create_new_delta_plan, source_plan, source_plan_id, timeout)

    def _get_staged_delta_plans(self, bts_id=0):
        """
        Get ASIR Webem uploaded delta plans info.

        :param int bts_id: BTS id - related to Test Line configuration
        :return list[dict]: list of ASIR Webem staged delta plan parameters. Example return value:
        [{'eid': 75, 'name': 'New commissioning 2022-04-23T15:37:04.627Z', 'source': 'none'}]
        """
        return self._perform_asir_operation(self.asir.get_staged_delta_plans)

    def _update_object_of_delta_plan(self, delta_plan_id, body, bts_id=0):
        """
        Update parameter of ASIR Webem staged delta plan.
        :param list body: in format:
        [
            {"operation":"create","dn":"ASI-1","moc":"HUBMOD","instanceId":"1"},
            {"operation":"create","dn":"ASI-1","moc":"HUBMOD"}
        ]
        :param str delta_plan_id: id of staged delta plan
        :param int bts_id: BTS id - related to Test Line configuration
        :return: None
        """
        return self._perform_asir_operation(self.asir.update_object_of_delta_plan, delta_plan_id, body)

    def _update_parameter_of_delta_plan(self, delta_plan_id, operation, dn, name, value, field=None, index=None,
                                        bts_id=0):
        """
        Update parameter of ASIR Webem staged delta plan.

        :param str delta_plan_id: id of staged delta plan
        :param str operation: modification operation, possible values: ["create", "update", "delete"]
        :param str dn: dist name of parameter
        :param str name: name of target parameter
        :param str value: new value of target parameter
        :param str field: structure name of target parameter
        :param int index: index of target parameter in the array
        :param int bts_id: BTS id - related to Test Line configuration
        :return: None
        """
        return self._perform_asir_operation(self.asir.update_parameter_of_delta_plan, delta_plan_id, operation, dn,
                                            name, value, field, index)

    def _migrate_nidd(self, delta_plan_id, target_nidd_version=None, timeout=60, bts_id=0):
        """
        Migrate ASIR Webem plan template to target nidd version.

        :param str delta_plan_id: id of staged delta plan to migration
        :param str target_nidd_version: target NIDD version, if not provided newest release NIDD will be chosen
        :param float timeout: time in seconds to finish the plan template migration
        :param int bts_id: BTS id - related to Test Line configuration
        :return dict: delta plan nidd migration result info
        :raises AsirOperationTimeout: exception raised when operation on ASIR exceeds the time limit
        """
        return self._perform_asir_operation(self.asir.migrate_nidd, delta_plan_id, target_nidd_version, timeout)

    def _activate_delta_plan(self, delta_plan_id, timeout=60, bts_id=0):
        """
        Activate ASIR Webem staged delta plan defined by delta plan id.

        :param str delta_plan_id: id of staged delta plan to activate
        :param float timeout: time in seconds to finish the delta plan operation
        :param int bts_id: BTS id - related to Test Line configuration
        :return dict: delta plan activation result info
        :raises AsirOperationTimeout: exception raised when operation on ASIR exceeds the time limit
        """
        return self._perform_asir_operation(self.asir.activate_delta_plan, delta_plan_id, timeout)

    def _get_delta_plan_file(self, delta_plan_id, local_dir_path, content_type="auto", file_name=None, timeout=60,
                             bts_id=0):
        """
        Get ASIR staged delta plan file defined by delta plan id.

        :param str delta_plan_id: id of staged delta plan to save.
        :param str local_dir_path: path to save delta file.
        :param content_type: type of delta file content:
            "auto" for short delta plan or "full" for full SCF containing delta plan.
        :param str file_name: name of delta file.
        :param float timeout: time in seconds to finish delta plan operation.
        :param Union[ASIRConnection,str] connection: ASIRConnection object or if used, string name alias.
        :return str: path to the file with delta file content.
        """
        if file_name is None:
            file_name = '{}_delta_scf.xml'.format(self.rest_alias.format(bts_id))
        if not os.path.exists(local_dir_path):
            os.makedirs(local_dir_path)
        return self._perform_asir_operation(self.asir.get_delta_plan_file, delta_plan_id, content_type, local_dir_path,
                                            file_name, timeout)

    def _delete_delta_plan(self, delta_plan_id, bts_id=0):
        """
        Delete ASIR Webem staged delta plan defined by delta plan id.

        :param str delta_plan_id: id of staged delta plan to delete
        :param int bts_id: BTS id - related to Test Line configuration
        :return: None
        """
        return self._perform_asir_operation(self.asir.delete_delta_plan, delta_plan_id)

