    @load_moler_configuration_from_tl()
    def get_hub_version(self, bts_id=0, du_id=0, ru_id=0):
        """
        Get HUB version

        :param      bts_id: ID of BTS
        :param      du_id:  DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param      ru_id:  RU id(Radio Unit) - id related to Test Line configuration
        :return:    string, output from executing the hostname command
                    Example: fzhub20
        """
        hub = self.get_hub_device(bts_id, du_id, ru_id)
        hostname_cmd = hub.get_cmd(cmd_name='hostname')
        return hostname_cmd()['hostname']

    def check_hub_version(self, hub_version, bts_id=0, du_id=0, ru_id=0):
        """
        Verify that HUB version is equal to given

        :param      hub_version: name of hub version
        :param      bts_id:      ID of BTS
        :param      du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param      ru_id:       RU id(Radio Unit) - id related to Test Line configuration
        :return:    True if hub version is correct otherwise False
        """
        return True if self.get_hub_version(bts_id, du_id, ru_id) == hub_version else False

    def get_antennas_info(self, bts_id=0, du_id=0, ru_id=0, hub_device=None):
        hub_device = hub_device or self.get_hub_version(bts_id, du_id, ru_id)
        antennas = {}
        pattern = r".*AntType: (\w+), fpgaVersion: (\w+), fpgaType: (\w+), DC status: (\w+), AntImageBufType: (\w+)," \
                  r" rrhNumber: (\d+).*"
        grep = hub_device.get_cmd(cmd_name="grep", cmd_params={"options": "'fpga.*Factory' /tmp/ant_discovery_log"})()
        for line in grep["LINES"]:
            match = re.search(pattern, line)
            if match:
                ant_type, fpga_version, fpga_type, dc_status, ant_image_buf_type, rrh_number = match.groups()
                antennas[int(rrh_number)] = {"ant_type": ant_type, "fpga_version": fpga_version, "fpga_type": fpga_type,
                                             "dc_status": dc_status, "ant_image_buf_type": ant_image_buf_type}
        return antennas

