        """
        Block antenna via ASIR-WebEM

        :param int bts_id: BTS id - related to Test Line configuration, default: 0
        :param int ant_id: Antenna id - related to Test Line configuration, default: 1
        :param int timeout: Time after which the reset is considered unsuccessful
        :return: None
        """
