    def _get_dist_name(self, dist_name_pattern):
        dist_names = self._get_all_dist_names(dist_name_pattern)
        if dist_names:
            return dist_names[0]

    def _get_all_dist_names(self, dist_name_pattern):
        active_dist_names = self._perform_asir_operation(self.asir.get_active_dist_names)
        _re_dist_name = re.compile(dist_name_pattern)
        dist_names = []
        for record in active_dist_names:
            dist_name = record['dn']
            if _re_dist_name.search(dist_name):
                dist_names.append(dist_name)

        return dist_names

    def _get_all_dist_names_and_uids(self, dist_name_pattern):
        active_dist_names = self._perform_asir_operation(self.asir.get_active_dist_names)
        _re_dist_name = re.compile(dist_name_pattern)
        records = []
        for record in active_dist_names:
            dist_name = record['dn']
            if _re_dist_name.search(dist_name):
                records.append(record)

        return records

    def _get_dist_name_for_given_unit_type(self, unit_id, unit_type):
        patterns = {
            'antenna': AsirDistNamePatterns.re_antmod_dist_name.format(unit_id),
            'hub': AsirDistNamePatterns.re_hubmod_dist_name.format(unit_id)}
        return self._get_dist_name(dist_name_pattern=patterns[unit_type])

    def _get_active_objects(self):
        """
        Get active objets from current delta plan

        :return: list of objects
        Sample results:
        [
            {
                "children": [
                    "ANTMOD-1",
                    "ANTMODPR-1",
                    "ASI_R-1",
                    "BTS-1",
                    "CMCADM-1",
                    "CMD-1",
                    "HUBMOD-1",
                    "HUBUACPR-1",
                    "PM-1",
                    "PMCADM-1",
                    "RFC-1",
                    "SECPRM-1"
                ],
                "dn": "ASI-1",
                "instanceId": "1",
                "moc": "ASI",
                "numberOfParameters": 1
            },
            {
                "children": [
                    "ANTRFSM-1",
                    "ANTRFSM-2",
                    "ANTRFSM-3"
                ],
                "dn": "ASI-1/ANTMOD-1",
                "instanceId": "1",
                "moc": "ANTMOD",
                "numberOfParameters": 5
            },
            {
                "children": [
                    "ANTANTL-1",
                    "ANTANTL-2"
                ],
                "dn": "ASI-1/ANTMOD-1/ANTRFSM-1",
                "instanceId": "1",
                "moc": "ANTRFSM",
                "numberOfParameters": 1
            },
    ...
        """
        staged_delta_plans = self._get_staged_delta_plans()
        if staged_delta_plans:
            delta_plan_id = staged_delta_plans[0]['eid']
        else:
            logging.debug('Create a new delta plan')
            delta_plan_id = self._create_new_delta_plan(source_plan='active')['eid']

        logging.debug("Staged DELTA_PLAN_ID {}".format(delta_plan_id))

        cm_instance = self.asir.store._get(self._connection_alias)._asir.cm.cm_api_instance
        active_objects = cm_instance.cm_plans_active_objects_get(eid=delta_plan_id)
        logging.debug("ACTIVE OBJECTS {}".format(active_objects))
        return active_objects

    @login_logout
    def verify_alarm_is_active(self, fault_id, bts_id=0):
        """
        Verify alarm is active via ASIR-WebEM

        :param int fault_id: fault index to be checked
        :param int bts_id: BTS id - related to Test Line configuration, default: 0
        :return: None
        """
        if self._verify_alarm_exist_in_active_alarms(fault_id=fault_id):
            logging.info("Alarm with id {} is active".format(fault_id))
        else:
            raise AlarmIsNotActive("Alarm with id {} is not active, it should be active".format(fault_id))

    @login_logout
    def verify_only_allowed_alarms_are_active(self, allowed_alarms, bts_id=0):
        """
        Verify if only allowed alarms are active

        :param list allowed_alarms: list of alarms fault ids that can be active
        :param int bts_id: BTS id - related to Test Line configuration, default: 0
        :return: None
        """

        unallowed_alarms = []
        active_alarms = self._perform_asir_operation(self.asir.get_active_alarms)
        logging.debug("Active alarms: {}".format(active_alarms))

        for active_alarm in active_alarms:
            if active_alarm['fault_id'] not in allowed_alarms:
                unallowed_alarms.append(active_alarm)

        if unallowed_alarms:
            raise AlarmIsActive("These alarms: {} are active, but are unallowed and should be inactive"
                                .format(unallowed_alarms))

    @login_logout
    def verify_alarm_is_not_active(self, fault_id, bts_id=0):
        """
        Verify alarm is not active via ASIR-WebEM

        :param int fault_id: fault index to be checked
        :param int bts_id: BTS id - related to Test Line configuration, default: 0
        :return: None
        """
        if not self._verify_alarm_exist_in_active_alarms(fault_id=fault_id, bts_id=bts_id):
            logging.info("Alarm with id {} is not active".format(fault_id))
        else:
            raise AlarmIsActive("Alarm with id {} is active, it should be inactive".format(fault_id))

    def _verify_alarm_exist_in_active_alarms(self, fault_id, bts_id=0):
        """
        Compare active ASIR-WebEM alarms with delivered alarm by Id of fault.

        :param int fault_id: fault index to be checked
        :param int bts_id: BTS id - related to Test Line configuration, default: 0
        :return: True if given alarm is active else False
        """
        active_alarms = self._perform_asir_operation(self.asir.get_active_alarms)
        for alarm in active_alarms:
            if int(alarm["fault_id"]) == int(fault_id):
                return True
        return False

    @staticmethod
    def _convert_scf_file_to_supported_nidd(scf_path, actual_nidd, supported_nidd):
        converted_scf_filename = "{}_nidd_migrated_to_{}.xml".format(os.path.basename(scf_path).split(".")[0],
                                                                     supported_nidd)
        converted_scf_path = os.path.join(os.path.dirname(scf_path), converted_scf_filename)
        with open(scf_path, "r+") as actual_scf:
            modified_scf_content = actual_scf.read().replace(actual_nidd, supported_nidd)
            actual_scf.close()
        with open(converted_scf_path, "w+") as converted_scf:
            converted_scf.write(modified_scf_content)
            converted_scf.close()

        return converted_scf_path

    @staticmethod
    def _compare_unit_statuses(statuses, id, expected_statuses={}):
        """
        Compering unit expected statuses with real statuses.
        param: dict statuses: ASIR Webem unit logical info.
        Example:
        [   {'text': 'enabled', 'title': 'Operational state', 'type': 'text'},
            {'text': 'Yes', 'title': 'Commissioned', 'type': 'text'},
            {'text': 'unblocked', 'title': 'Local state', 'type': 'text'},
            {'text': 'working', 'title': 'Hardware state', 'type': 'text'},
            {'text': 'detected', 'title': 'Software state', 'type': 'text'},
            {'text': 'Off', 'title': 'Fronthaul status LED color', 'type': 'text'},
            {'text': 'Off', 'title': 'RF status LED color', 'type': 'text'},
            {'text': 'Off', 'title': 'Unit status LED color', 'type': 'text'}]
        :param int id: id of ASIR unit check.
        :param dict expected_statuses: Expected values of ASIR unit statuses.
        :return: None
        """
        tmp_statuses = expected_statuses.copy()
        for status in statuses:
            status['title'] = status['title'].lower().replace(" ", "")
            if status['title'] in expected_statuses.keys():
                if status['text'].lower() != expected_statuses[status['title']]:
                    raise InvalidStatuses("Unexpected statuses {} should be {} but is {} for id {}".format(
                        status['title'], expected_statuses[status['title']].lower(), status['text'].lower(), id))
                else:
                    del tmp_statuses[status['title']]
        if tmp_statuses:
            raise InvalidStatuses("status not found {}".format(tmp_statuses))

    @login_logout
    def verify_antmod_status(self, ant_ids=[1], expected_statuses=None, bts_id=0):
        """
        Checking states for ANTMODs

        :param list ant_ids: ids of ANTMODs to check
        Example : ant_ids = [1, 2]
        :param dict expected_statuses: Expected values of ant statuses. Only a few statuse can be checked
        or all of them
        Example : expected_statuses = {'operationalState': 'enabled', 'commissioned': 'Yes', 'localState': 'unblocked',
                  'hardwareState': 'working', 'softwareState': 'detected', 'fronthaulStatusLedColor': 'Off',
                  'rfStatusLedColor': 'Off', 'unitStatusLedColor': 'Off'}
        :param int bts_id: BTS id - related to Test Line configuration, default: 0
        :return: None
        """
        ant_ids_str = [str(ant_id) for ant_id in ant_ids]
        ant_dist_names = self._get_all_dist_names_and_uids(AsirDistNamePatterns.re_antmod_dist_name.
                                                           format(r'({})'.format('|'.join(ant_ids_str))))
        logging.debug("Checking status for DIST_NAMES: {}".format(ant_dist_names))
        expected_statuses = {status.lower(): expected_statuses[status].lower() for status in expected_statuses.keys()}
        for record in ant_dist_names:
            ant_id = self._get_id_from_dist_name(record['dn'])
            logging.info("Checking status for antenna: {}".format(ant_id))
            statuses = self._get_states_from_logical_info(self.get_unit_logical_info(uid=record['uid'], bts_id=bts_id))
            logging.info("Expected AntMod Statuses {} ".format(expected_statuses))
            logging.info("Current AntMod Statuses {}".format(statuses))
            self._compare_unit_statuses(statuses, ant_id, expected_statuses)
            logging.info("Status for antenna: {} is as expected".format(ant_id))

