    @login_logout
    def verify_status_of_asir_cells(self, cell_ids=[], expected_asir_cell_status=None, bts_id=0):
        """
        Checking cells status of gnb or enb in Asir WebEM

        :param string expected_asir_cell_status:  Expected gnb or enb cell status in Asir WEM  [ operational / failed ]
        :param list cell_ids: ids of Cells to check from WEM, in case of not passing any cell_id all gnb/enb cells will be checked
        :param int bts_id: BTS id - related to Test Line configuration, default: 0
        :return: None
        """

        def check_status(cell_label, check_all_cells=False):
            for ele in info:
                if ele['description'] and (
                        cell_label in ele['description']['label'] or 'RFC-' in ele['description']['label']):
                    if check_all_cells or cell_label == ele['description']['label']:
                        logging.info(
                            'Asir Cell : {}  Status : {}'.format(ele['description']['label'], ele['status']['state']))
                        if ele['status']['state'] != expected_asir_cell_status:
                            raise InvalidStatuses("Unexpected statuses")

        mrbts_id = GenericBts().get_global_bts_id()
        info = self._perform_asir_operation(self.asir.get_site_logical_info)
        if cell_ids:
            for cell in cell_ids:
                check_status(cell_label='BTS{}.{}'.format(mrbts_id, cell))
        else:
            check_status(cell_label='BTS{}'.format(mrbts_id), check_all_cells=True)

    def verify_status_of_all_asir_cells_is_operational(self, bts_id=0):
        self.verify_status_of_asir_cells(expected_asir_cell_status='operational', bts_id=bts_id)

