    @login_logout
    def get_site_logical_info(self, bts_id=0):
        return self._perform_asir_operation(self.asir.get_site_logical_info)

    def get_all_cells_with_antenna_mapping(self, bts_id=0):
        """
        Mapping antennas to their corresponding cells

        :return list: antennas mapped to corresponding cells. Example return value:
        [{'id': 1, 'dn': 'ASI-1/ASI_R-1/BTS_R-1/CELL_R-1', 'uid': '22', 'antennas': [{'id': 4, 'dn': 'ASI-1/ANTMOD-4',
        'uid': '13'}]]
        """
        asir_site_info = self.get_site_logical_info(bts_id=bts_id)
        all_cells = self.get_all_cells_info(bts_id=bts_id)
        all_antennas = self.get_all_antennas_info(bts_id=bts_id)

        for asir_info in asir_site_info:
            for cell_info in all_cells:
                if asir_info['uid'] == cell_info['uid']:
                    cell_info['antennas'] = []
                    for connection in asir_info['connections']:
                        for connector in connection['connectors']:
                            for ant_info in all_antennas:
                                if connector['dst_uid'] == ant_info['uid']:
                                    cell_info['antennas'].append(ant_info)

        return all_cells

    def get_all_hubs_with_cell_and_antenna_mapping(self, scf_file_path=None, bts_id=0):
        """
        Mapping antennas, cells to their corresponding hubs
        :param       scf_file_path:  optional, path to ASiR scf file (if not specified,
                                        there will be no information about antenna ports in the final dict)
        :return dict:
        {'NH221300907': {'name': 'HUBMOD-8', 'id': '8', 'uid': 'e', 'type': 'APHG', 'cells': {'BTS78301.1':
        {'uid': '47', 'id': '1'}}, 'antennas': {'ANTMOD-10': {'id': '10', 'uid': '1c',
        'serial_number': 'NH191210186', 'type': 'AHENB', 'ant_port_name': 'ANTPORT-1', 'ant_port_id': '1'}}}}
        """
        site_logical_info = self.get_site_logical_info(bts_id=bts_id)
        hubs = {}
        cells = {}
        antennas = {}
        for component in site_logical_info:
            try:
                if component["description"]["label"] == "pRRHs of HUB":
                    hub_uid, cells_uid, antennas_uid = self._get_hub_connections_from_site_logical_info(component)
                    if hub_uid is None:
                        continue
                    hub_info = self._get_unit_general_info_from_logical_info(unit_uid=hub_uid)
                    hubs[hub_info["serial_number"]] = {}
                    hubs[hub_info["serial_number"]]["name"] = hub_info["name"]
                    hubs[hub_info["serial_number"]]["id"] = hub_info["id"]
                    hubs[hub_info["serial_number"]]["uid"] = hub_uid
                    hubs[hub_info["serial_number"]]["type"] = hub_info["type"]
                    hubs[hub_info["serial_number"]]["cells"] = {}
                    hubs[hub_info["serial_number"]]["antennas"] = {}
                    for cell_uid in cells_uid:
                        try:
                            cells[cell_uid].append(hub_info["serial_number"])
                        except KeyError:
                            cells[cell_uid] = [hub_info["serial_number"]]
                    for antenna_uid in antennas_uid:
                        try:
                            antennas[antenna_uid].append(hub_info["serial_number"])
                        except KeyError:
                            antennas[antenna_uid] = [hub_info["serial_number"]]
                elif component["uid"] in list(cells):
                    cell_info = {}
                    cell_info["uid"] = component["uid"]
                    cell_info["id"] = component["description"]["label"].split(".")[-1]
                    for hub_sn in cells[component["uid"]]:
                        hubs[hub_sn]["cells"][component["description"]["label"]] = cell_info
            except TypeError:
                pass
        for antenna_uid in list(antennas):
            antenna_info = self._get_unit_general_info_from_logical_info(unit_uid=antenna_uid)
            antenna = {}
            antenna["id"] = antenna_info["id"]
            antenna["uid"] = antenna_uid
            antenna["serial_number"] = antenna_info["serial_number"]
            antenna["type"] = antenna_info["type"]
            for hub_sn in antennas[antenna_uid]:
                hubs[hub_sn]["antennas"][antenna_info["name"]] = antenna
        if scf_file_path is not None:
            self._add_antennas_port_info_based_on_asir_scf(hubs, scf_file_path)
        return hubs

    def _add_antennas_port_info_based_on_asir_scf(self, hubs_info, scf_file_path):
        antmod_info = self.get_all_params_under_class_name(scf_file_path, class_name="com.nokia.asi:ANTMOD")
        for hub_sn, hub_parameters in hubs_info.items():
            for antenna_name, antenna_params in hub_parameters['antennas'].items():
                for antmod in antmod_info:
                    if antmod["dist_name"].split("/")[-1] == antenna_name:
                        antenna_params["ant_port_name"] = antmod["params"]["antPortDN"].split("/")[-1]
                        hub_logical_info = self.get_unit_logical_info(hub_parameters["uid"])
                        for paragraph in hub_logical_info["paragraphs"]:
                            if paragraph["title"] == "ASiR-pRRH port":
                                port_id_location = paragraph["paragraphs"][0]["headers"].index("Port ID")
                                port_dn_location = paragraph["paragraphs"][0]["headers"].index("Paired managed object")
                                for port in paragraph["paragraphs"][0]["rows"]:
                                    if port[port_dn_location] == antmod["params"]["antPortDN"]:
                                        antenna_params["ant_port_id"] = port[port_id_location]

    @login_logout
    def get_unit_logical_info(self, uid, bts_id=0):
        return self._perform_asir_operation(self.asir.get_unit_logical_info, uid)

    @staticmethod
    def _get_hub_connections_from_site_logical_info(site_logical_info_component):
        antennas_uid = []
        cells_uid = []
        hub_uid = None
        for values in site_logical_info_component["connections"]:
            if values["type"] == "parent":
                continue
            elif values["type"] == "containment":
                antennas_uid = [unit["dst_uid"] for unit in values["connectors"]]
            elif values["type"] == "link":
                hub_uid = values["connectors"][0]["dst_uid"]
                cells_uid = [unit["dst_uid"] for unit in values["connectors"][2:]]
        return hub_uid, cells_uid, antennas_uid

    def _get_unit_general_info_from_logical_info(self, unit_uid):
        unit_info = {}
        unit = self.get_unit_logical_info(uid=unit_uid)
        for paragraphs in unit["paragraphs"]:
            if paragraphs["title"] == "General Information":
                for info in paragraphs["paragraphs"]:
                    if info["title"].lower() == "serial number":
                        unit_info["serial_number"] = info["text"]
                    elif info["title"].lower() == "product name":
                        unit_info["type"] = info["text"]
                    elif info["title"].lower() == "paired managed object":
                        unit_info["name"] = info["text"].split("/")[-1]
                        unit_info["id"] = unit_info["name"].split("-")[-1]
                return unit_info

    @login_logout
    def verify_units_state(self, bts_id=0, units_uid=[], expected_status="operational"):
        """
        Verify units state on ASIR WEBEM
        :param units_uid: list with units uid to be checked
        :param expected_status: wanted status of units
        :return:
        """
        failed_units = []
        logical_info = self._perform_asir_operation(self.asir.get_site_logical_info)
        for unit in logical_info:
            if unit["status"] is not None and unit["uid"] in units_uid:
                if unit["status"]["state"] == expected_status:
                    logging.debug("unit {} expected status: {}".format(unit["description"]["label"], expected_status))
                else:
                    failed_units.append("unit {} unexpected status: {}".format(
                        unit["description"]["label"], unit["status"]["state"]))
        if failed_units:
            raise AsirNotOnAir("\n".join(failed_units))

