    @login_logout
    def _check_if_parallel_sessions_are_active(self, bts_id=0):
        """
        Checking if parallel sessions are active, if not logging warn to console
        :return: None
        """
        import xml.etree.ElementTree as ET
        self._perform_asir_operation(self.asir.get_current_scf_file, "/tmp/", "temp_asir_scf.xml")
        asir_scf = ET.parse("/tmp/temp_asir_scf.xml")
        if asir_scf.find(".//*[@name='{}']".format("actParallelUserSessions")) is None or \
                asir_scf.find(".//*[@name='{}']".format("actParallelUserSessions")).text != "true" or \
                int(asir_scf.find(".//*[@name='{}']".format("maxParallelUserSessions")).text) < 2:
            log_warn_to_console("parameters actParallelUserSessions and/or maxParallelUserSessions not defined "
                                "properly in asir webem, if you will log to asir-webem, can cause exepctions",
                                log_hierarchy=3)

