    def get_cell_dist_names_connected_to_antena(self, ant_id, bts_id=0):
        """
        Get distNames of cells connected to a given antenna
        :param ant_id: antenna ID from ASIR configuration
        :param bts_id: BTS id - related to Test Line configuration
        :return: list of cells' distNames
        """
        antenna_mapping = self.get_all_cells_with_antenna_mapping(bts_id=bts_id)
        logging.debug(f'Antenna mapping: {antenna_mapping}')
        cells_connected_to_antenna = filter(lambda cell: self._filter_cells(cell, ant_id), antenna_mapping)
        logging.debug(f'Cells connected to antenna ID={ant_id}: {cells_connected_to_antenna}')
        cells_connected_to_antenna_dist_names = []
        for cell in cells_connected_to_antenna:
            cell_info = self.get_unit_logical_info(uid=cell['uid'], bts_id=bts_id)
            cell_dist_name = cell_info['paragraphs'][0]['paragraphs'][0]['text']
            cells_connected_to_antenna_dist_names.append(cell_dist_name)
        logging.debug(f'distNames of cells connected to antenna ID={ant_id}: {cells_connected_to_antenna_dist_names}')
        return cells_connected_to_antenna_dist_names

    @load_moler_configuration_from_tl()
    def _get_power_consumption_of_antenna_ports_group(self, group_number, bts_id=0, du_id=0, ru_id=0):
        hub = self.get_hub_device(bts_id, du_id, ru_id)
        ants_group_info = []
        cat_cmd = hub.get_cmd(cmd_name="cat", cmd_params={"path": "/sys/bus/i2c/devices/{0}/port_info"
                              .format(group_number)})
        for ant in cat_cmd()["LINES"][1:]:
            ants_group_info.append(dict(zip(['port_id', 'mode', 'mVolts', 'mAmps'], ant.split())))
        return ants_group_info

    def get_power_consumption_of_all_antenna_ports(self, hubs_id, bts_id=0, du_id=0):
        """
        Get information about power consumption for all antennas of given hubs

        :param      hubs_id:        list of hub IDs, related to Test Line
        :param      bts_id:         ID of BTS
        :param      du_id:          DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:    list of dicts,  contains information about all antenna ports for hubs
                    Example:
                    [{'hub_id': '1',
                    'ports': [{'port': '1', 'mode': 'auto', 'mVolts': '56000', 'mAmps': '500'},
                    {'port': '2', 'mode': 'auto', 'mVolts': '0', 'mAmps': '0'},
                    {'port': '3', 'mode': 'auto', 'mVolts': '0', 'mAmps': '0'},
                    {'port': '4', 'mode': 'auto', 'mVolts': '0', 'mAmps': '0'},
                    ...]}]
        """
        hub_ports_power = []
        for hub_id in hubs_id:
            groups = ["1-0022", "1-0024", "1-0026"] if self.check_hub_version("fzhub20", bts_id, du_id, hub_id - 1) \
                else ["1-0020", "1-0022", "1-0024"]
            ports_info = []
            for group_number in groups:
                ports_info.extend(self._get_power_consumption_of_antenna_ports_group(group_number, bts_id, du_id,
                                                                                     hub_id - 1))
            reindexing = 1
            for port in ports_info:
                port["port_id"] = str(reindexing)
                reindexing += 1
            hub_ports_power.append({"hub_id": str(hub_id), "ports": ports_info})
        return hub_ports_power

    def verify_power_consumption_of_all_antennas(self, scf_file_path, min_power=270, bts_id=0, du_id=0):
        """
        Check that the power consumption is correct for antennas of all hubs

        :param      scf_file_path:  Path to ASiR scf file
        :param      min_power:      minimum valid power consumption value
        :param      bts_id:         ID of BTS
        :param      du_id:          DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :raises:    taf.rfrl.bts.devices.exceptions.WrongPowerConsumption
        """
        hub_ants_info = self.get_all_hubs_with_cell_and_antenna_mapping(scf_file_path)
        logging.debug("Mapped hubs and antennas:\n {}".format(hub_ants_info))
        hubs_id = [int(hub_parameters["id"]) for hub_sn, hub_parameters in hub_ants_info.items()]
        hub_ports_power = self.get_power_consumption_of_all_antenna_ports(hubs_id, bts_id, du_id)
        logging.debug("Mapped hubs and port power consumption:\n {}".format(hub_ports_power))
        wrong_power_ants = {}
        for hub_sn, hub_parameters in hub_ants_info.items():
            for antenna_name, antenna_params in hub_parameters["antennas"].items():
                for hub_power in hub_ports_power:
                    if hub_parameters["id"] == hub_power["hub_id"]:
                        for hub_port in hub_power["ports"]:
                            if hub_port["port_id"] == antenna_params["ant_port_id"] and \
                                    int(hub_port["mAmps"]) < min_power:
                                wrong_power_ants[antenna_name] = "{0} mAmps".format(hub_port["mAmps"])
        if wrong_power_ants:
            raise WrongPowerConsumption("Inappropriate power level for following ants: {0}, should be min. {1} mAmps"
                                        .format(str(wrong_power_ants), min_power))

    def get_all_params_under_class_name(self, scf_file_path, class_name, bts_id=0):
        """
        Get parameter value from scf
        :param class_name: scf class name: eg: "com.nokia.srbts.nrbts:NRCELL", "com.nokia.srbts.mnl:FEATCADM"
        :param bts_id:  int
        :param du_id: int
        :return: list of dicts contains keys: 'dist_name', 'params'
            eg:
            [
                {
                    "dist_name":"MRBTS-76065/MNL-1/MNLENT-1/FEATCADM-1",
                    "params":{
                             "actAldSharing":"false",
                             "actAldSwUpdate":"false",
                             "actAntennaPathDelayMeasurement":"false",
                             "actApts":"false",
                             ....
                    }
                },
                ...
            ]
        """
        with open(scf_file_path, 'r') as asir_scf:
            asir_scf_content = asir_scf.read()
            all_params_under_class_name = get_all_params_under_class_name(scf_file_content=asir_scf_content,
                                                                          class_name=class_name)
            return all_params_under_class_name

    def _filter_cells(self, cell, ant_id):
        antennas = cell['antennas']
        for antenna in antennas:
            if antenna['id'] == int(ant_id):
                return True
        return False

